import React from 'react';

const PageVisitCounter = () => {
    // Removed the unused 'visits' state and fetch logic to fix the ESLint warning

    const counterStyle = {
        padding: '12px 20px',
        fontSize: '0.85rem',
        color: '#1e3c72',
        fontWeight: '600',
        textAlign: 'center',
        background: '#ffffff',
        border: '1px solid #ddd',
        borderRadius: '12px',
        display: 'inline-block',
        boxShadow: '0 2px 8px rgba(0,0,0,0.05)',
        marginTop: '10px'
    };

    const textStyle = {
        margin: '0 0 8px 0',
        fontSize: '0.9rem',
        color: '#555'
    };

    return (
        <div style={counterStyle}>
            <p style={textStyle}>Total Page Visits</p>
            <img 
                src="https://count.getloli.com/get/@infinitylbsl?theme=rule_73" 
                alt="visitor count tracker" 
                style={{ display: 'block', margin: '0 auto' }}
            />
        </div>
    );
};

export default PageVisitCounter;
